        'Ready': 'Listo',
        'Real-time for US equities where licensed, otherwise delayed. Also covers FX and crypto. Each symbol in a batch costs one credit.': 'Tiempo real para acciones de EE. UU. donde hay licencia; si no, con retraso. También cubre divisas y cripto. Cada símbolo en un lote cuesta un crédito.',
        'Real-time means the last trade as it happens. Delayed usually means 15 minutes behind for US stocks on free plans. End-of-day means yesterday\'s close until the market shuts today. Crypto trades around the clock and FX five days a week, so "closed" means something different for each.': 'Tiempo real significa la última operación al momento. Con retraso suele significar 15 minutos atrás para acciones de EE. UU. en planes gratuitos. Al cierre significa el cierre de ayer hasta que el mercado cierre hoy. Las cripto operan todo el día y las divisas cinco días a la semana, así que "cerrado" significa algo distinto en cada caso.',
