        'Ready': 'Pronto',
        'Real-time for US equities where licensed, otherwise delayed. Also covers FX and crypto. Each symbol in a batch costs one credit.': 'Tempo real para ações dos EUA quando licenciado; senão, com atraso. Também cobre câmbio e cripto. Cada símbolo em um lote custa um crédito.',
        'Real-time means the last trade as it happens. Delayed usually means 15 minutes behind for US stocks on free plans. End-of-day means yesterday\'s close until the market shuts today. Crypto trades around the clock and FX five days a week, so "closed" means something different for each.': 'Tempo real significa o último negócio no momento em que acontece. Com atraso geralmente significa 15 minutos atrás para ações dos EUA em planos gratuitos. Fechamento significa o fechamento de ontem até o mercado fechar hoje. Cripto negocia o dia todo e câmbio cinco dias por semana, então "fechado" significa algo diferente em cada caso.',
