        'Not investment advice. Quotes may be delayed and come from third-party APIs using your own keys. Alerts fire only while a tab is open. Your watchlist, holdings, rules and keys stay in your browser and are never sent anywhere but the data provider. Stocks is a monitoring and visualization tool only — it does not place trades, connect to brokerages, or move money.': 'Не является инвестиционной рекомендацией. Котировки могут запаздывать и поступают из сторонних API с вашими собственными ключами. Оповещения срабатывают только при открытой вкладке. Ваш список, позиции, правила и ключи остаются в браузере и отправляются только провайдеру данных. Stocks — только инструмент мониторинга и визуализации: он не совершает сделок, не подключается к брокерам и не переводит деньги.',
