        'A one-minute tour of the screen. Stocks shows prices, charts and your own portfolio — it never trades and gives no advice. You can replay this from Learn.': 'Минутный обзор экрана. Stocks показывает цены, графики и ваш собственный портфель — он никогда не торгует и не даёт советов. Повторить обзор можно в разделе «Обучение».',
        'A save to this browser failed — storage is full ({size} in use). Export your data, then clear cached charts with "Clear all data" or free space in your browser settings. Until then, new holdings, rules and settings may not survive a reload.': 'Не удалось сохранить в этом браузере — хранилище заполнено (занято {size}). Экспортируйте данные, затем очистите кэш графиков через «Стереть все данные» или освободите место в настройках браузера. До тех пор новые позиции, правила и настройки могут не сохраниться после перезагрузки.',
        'A starting layout replaces your tabs and widgets; your watchlist, transactions, alerts and notes in Settings are kept.': 'Стартовый макет заменяет ваши вкладки и виджеты; список наблюдения, сделки, оповещения и заметки в настройках сохраняются.',
