        'Read in this page only — the file is never uploaded. Supported: Interactive Brokers, Schwab, Fidelity, Vanguard, Robinhood, eToro, Trading 212, Degiro, GBM+, Bitso, Coinbase, Kraken and a generic format.': 'Файл читается только на этой странице и никуда не загружается. Поддерживаются: Interactive Brokers, Schwab, Fidelity, Vanguard, Robinhood, eToro, Trading 212, Degiro, GBM+, Bitso, Coinbase, Kraken и универсальный формат.',
        'Read-only': 'Только чтение',
        'Read-only here. Edit notes in the main window.': 'Здесь только чтение. Редактируйте заметки в главном окне.',
        'Ready': 'Готов',
        'Real-time for US equities where licensed, otherwise delayed. Also covers FX and crypto. Each symbol in a batch costs one credit.': 'Реальное время для акций США при наличии лицензии, иначе с задержкой. Также охватывает валюты и криптовалюты. Каждый символ в пакете стоит один кредит.',
        'Real-time means the last trade as it happens. Delayed usually means 15 minutes behind for US stocks on free plans. End-of-day means yesterday\'s close until the market shuts today. Crypto trades around the clock and FX five days a week, so "closed" means something different for each.': 'Реальное время — последняя сделка в момент её совершения. С задержкой обычно означает отставание на 15 минут для акций США на бесплатных тарифах. На закрытие — вчерашнее закрытие, пока рынок не закроется сегодня. Криптовалюты торгуются круглосуточно, а валюты — пять дней в неделю, поэтому «закрыт» означает для них разное.',
        'Realized': 'Реализовано',
