        'Recent news': 'Свежие новости',
        'Reconnect to the panel window if it is still open, or open it again if it is not.': 'Переподключитесь к окну панели, если оно ещё открыто, или откройте его снова.',
        'Record holdings and dividends in Transactions to track income.': 'Внесите позиции и дивиденды в «Сделки», чтобы отслеживать доход.',
        'Record holdings in Transactions for portfolio alerts to measure anything.': 'Внесите позиции в «Сделки», чтобы оповещения по портфелю могли что-то измерять.',
        'Record holdings in Transactions to see how your money is spread.': 'Внесите позиции в «Сделки», чтобы увидеть, как распределены ваши деньги.',
        'Record holdings in Transactions to see performance.': 'Внесите позиции в «Сделки», чтобы увидеть доходность.',
        'Record the missing buy first, or tick “deliberate short sale” under More options.': 'Сначала внесите недостающую покупку или отметьте «намеренная короткая продажа» в разделе «Дополнительно».',
        'Record what you own to see its value and gains. Entered by hand or imported from a broker CSV; never connected to an account.': 'Внесите то, чем владеете, чтобы видеть стоимость и прибыль. Вручную или импортом CSV от брокера; никогда не подключается к счёту.',
