        'Real-time for US equities where licensed, otherwise delayed. Also covers FX and crypto. Each symbol in a batch costs one credit.': 'ライセンスのある米国株はリアルタイム、それ以外は遅延。為替と暗号資産にも対応。一括取得では銘柄ごとに1クレジットかかります。',
